function validate([operations, args]) {
  if (operations[0] !== 'AutocompleteSystem' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with AutocompleteSystem(sentences, times).';
  const [sentences, times] = args[0];
  if (!Array.isArray(sentences) || !Array.isArray(times) || sentences.length !== times.length) return 'sentences and times need the same length.';
  if (sentences.length < 1 || sentences.length > 100) return 'Give 1 to 100 sentences.';
  const words = /^[a-z]+( [a-z]+)*$/;
  if (sentences.some(s => typeof s !== 'string' || s.length > 100 || !words.test(s))) return 'Each sentence has 1 to 100 characters: lowercase words separated by single spaces.';
  if (new Set(sentences).size !== sentences.length) return 'The sentences must be distinct.';
  if (times.some(t => !Number.isInteger(t) || t < 1 || t > 50)) return 'Each times value is between 1 and 50.';
  if (operations.length - 1 > 5000) return 'At most 5000 calls to input.';
  let typed = '';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'input') return 'Only input can follow the constructor.';
    const c = args[i][0];
    if (typeof c !== 'string' || !/^[a-z #]$/.test(c)) return 'c is one lowercase letter, a space or #.';
    if (c === '#') {
      if (!words.test(typed) || typed.length > 200) return 'Each typed sentence has 1 to 200 characters of single-spaced lowercase words before #.';
      typed = '';
    } else {
      typed += c;
      if (typed.length > 200 || typed[0] === ' ' || typed.includes('  ')) return 'Typed sentences use single spaces between words and stay within 200 characters.';
    }
  }
  return null;
}

