class AutocompleteSystem {
  constructor(sentences, times) {
    this.root = { children: new Map(), sentences: new Set() };
    this.counts = new Map();
    this.typed = '';
    this.node = this.root;
    for (let i = 0; i < sentences.length; i++) {
      this.add(sentences[i], times[i]);
    }
  }

  add(sentence, times) {
    this.counts.set(sentence, (this.counts.get(sentence) || 0) + times);
    let node = this.root;
    for (const ch of sentence) {
      if (!node.children.has(ch)) {
        node.children.set(ch, { children: new Map(), sentences: new Set() });
      }
      node = node.children.get(ch);
      node.sentences.add(sentence);
    }
  }

  input(c) {
    if (c === '#') {
      this.add(this.typed, 1);
      this.typed = '';
      this.node = this.root;
      return [];
    }
    this.typed += c;
    if (this.node !== null) {
      this.node = this.node.children.get(c) || null;
    }
    if (this.node === null) {
      return [];
    }
    const matches = [...this.node.sentences];
    matches.sort((a, b) => this.counts.get(b) - this.counts.get(a) || (a < b ? -1 : 1));
    return matches.slice(0, 3);
  }
}

