class AutocompleteSystem {
  constructor(sentences, times) {
    this.history = new Map();
    sentences.forEach((s, i) => this.history.set(s, times[i]));
    this.current = '';
  }
  input(c) {
    if (c === '#') {
      this.history.set(this.current, (this.history.get(this.current) || 0) + 1);
      this.current = '';
      return [];
    }
    this.current += c;
    // Scan the whole history and rank the matches by count, then by character codes.
    const found = [...this.history.entries()].filter(([s]) => s.slice(0, this.current.length) === this.current);
    found.sort((x, y) => {
      if (x[1] !== y[1]) return y[1] - x[1];
      for (let i = 0; i < Math.min(x[0].length, y[0].length); i++) {
        if (x[0].charCodeAt(i) !== y[0].charCodeAt(i)) return x[0].charCodeAt(i) - y[0].charCodeAt(i);
      }
      return x[0].length - y[0].length;
    });
    return found.slice(0, 3).map(([s]) => s);
  }
}

