function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const large = size === 'large';
  const letters = large ? 'abcde' : 'ab';
  const vocab = [];
  while (vocab.length < (large ? 14 : 5)) {
    const word = Array.from({ length: 1 + pick(large ? 5 : 2) }, () => letters[pick(letters.length)]).join('');
    if (!vocab.includes(word)) vocab.push(word);
  }
  const makeSentence = (maxWords, maxLength) => {
    let sentence = vocab[pick(vocab.length)];
    const words = 1 + pick(maxWords);
    for (let w = 1; w < words; w++) {
      const next = sentence + ' ' + vocab[pick(vocab.length)];
      if (next.length > maxLength) break;
      sentence = next;
    }
    return sentence;
  };
  const count = large ? 60 + pick(41) : 1 + pick(4);
  const sentences = [];
  for (let tries = 0; sentences.length < count && tries < 5000; tries++) {
    const sentence = makeSentence(large ? 30 : 3, 100);
    if (!sentences.includes(sentence)) sentences.push(sentence);
  }
  const times = sentences.map(() => 1 + pick(large ? 50 : 3));
  const operations = ['AutocompleteSystem'];
  const args = [[sentences, times]];
  const limit = large ? 500 : 6 + pick(20);
  while (operations.length < limit) {
    const roll = rand();
    const text = roll < 0.4 ? sentences[pick(sentences.length)] : makeSentence(large ? 8 : 3, 200);
    const cut = roll > 0.85 ? 1 + pick(text.length) : text.length;
    for (const c of text.slice(0, cut).trimEnd() + '#') {
      if (operations.length >= limit) break;
      operations.push('input');
      args.push([c]);
    }
  }
  return [operations, args];
}
